import itertools

# vertices 0..10
n = 11

# fixed edges
fixed = {(1,10), (0,4), (0,8), (2,9)}

# try all possible bipartitions that respect fixed edges (i.e., no edge within same part)
# We can assign colors 0/1.

def check_partition(colors):
    # colors: dict vertex->0/1
    for u,v in fixed:
        if colors[u] == colors[v]:
            return False
    return True

# generate all bipartitions (2^11 / 2 = 1024 essentially)
valid_partitions = []
for mask in range(1 << n):
    colors = {}
    for v in range(n):
        colors[v] = (mask >> v) & 1
    # avoid complement duplicates? just check
    if check_partition(colors):
        valid_partitions.append(colors)

len(valid_partitions)

